test('verifyProof accepts the minimal derived set', () => {
  const chain = makeChain([
    { name: 'example.com' },
    { name: 'www.example.com' },
    { name: 'mail.example.com' },
    { name: 'a.b.example.com' },
  ]);
  const r = chain.validate('nope.example.com');
  assert.strictEqual(r.verdict, 'NXDOMAIN');
  const v = chain.verifyProof('nope.example.com', r.cover);
  assert.strictEqual(v.ok, true, v.reason);
});

test('verifyProof rejects missing records', () => {
  const chain = makeChain([
    { name: 'example.com' },
    { name: 'www.example.com' },
    { name: 'mail.example.com' },
    { name: 'a.b.example.com' },
  ]);
  const r = chain.validate('nope.example.com');
  const v = chain.verifyProof('nope.example.com', r.cover.slice(0, r.cover.length - 1));
  assert.strictEqual(v.ok, false);
