test('verifyProof rejects extra records', () => {
  const chain = makeChain([
    { name: 'example.com' },
    { name: 'www.example.com' },
    { name: 'mail.example.com' },
    { name: 'a.b.example.com' },
  ]);
  const r = chain.validate('nope.example.com');
  const extra = chain.records.map((x) => chain.ownerLabel(x.ownerKey)).find((o) => !r.cover.includes(o));
  const v = chain.verifyProof('nope.example.com', r.cover.concat(extra));
