test('verifyProof rejects owners that are not in the chain', () => {
  const chain = makeChain([{ name: 'example.com' }, { name: 'www.example.com' }]);
  const v = chain.verifyProof('example.com', [base32hexEncode(crypto.randomBytes(20))]);
