test('verifyProof rejects a forged wildcard owner', () => {
  const chain = makeChain([
    { name: 'example.com' },
    { name: 'www.example.com' },
    { name: '*.example.com' },
  ]);
  // Supply the correct CE + NC + a *foreign* existing owner instead of the
  // real wildcard match.
  const good = chain.validate('foo.example.com');
  assert.strictEqual(good.verdict, 'WILDCARD');
  const foreign = chain.records.map((x) => chain.ownerLabel(x.ownerKey)).find((o) => !good.cover.includes(o));
  const forged = good.cover.filter((o) => o !== base32hexEncode(hashName('*.example.com', SALT, ITER)));
  forged.push(foreign);
  const v = chain.verifyProof('foo.example.com', forged);
  assert.strictEqual(v.ok, false);
});

