test('hex, base32hex and Buffer inputs yield identical verdicts', () => {
  const names = [
    { name: 'example.com' },
    { name: 'www.example.com' },
    { name: 'mail.example.com' },
    { name: 'a.b.example.com' },
    { name: '*.example.com' },
  ];
  const b32 = buildRecords(names);
  const toHex = (r) => ({
    owner: Buffer.from(base32hexDecode(r.owner)).toString('hex'),
    next: Buffer.from(base32hexDecode(r.next)).toString('hex'),
    flags: r.flags, salt: r.salt, iterations: r.iterations,
  });
  const toBuf = (r) => ({
    owner: base32hexDecode(r.owner),
    next: base32hexDecode(r.next),
    flags: r.flags, salt: r.salt, iterations: r.iterations,
  });
  const fromB32 = new Nsec3Chain(b32);
  const fromHex = new Nsec3Chain(b32.map(toHex));
  const fromBuf = new Nsec3Chain(b32.map(toBuf));
  for (const q of ['foo.example.com', 'www.example.com', 'nope.example.com']) {
    const a = fromB32.validate(q);
    assert.deepStrictEqual(fromHex.validate(q), a, q);
    assert.deepStrictEqual(fromBuf.validate(q), a, q);
  }
  assert.deepStrictEqual(fromHex.verifyProof('foo.example.com', fromB32.validate('foo.example.com').cover).ok, true);
});

