 * 6. Performance: 1e6-record chain, 1e5 queries, < 5s budget       *
 * ---------------------------------------------------------------- */

test('perf: 1M-record chain + 100k queries within 5s', () => {
  const N = 1_000_000;
  const Q = 100_000;
  const saltHex = 'deadbeef';
  const iterations = 0;

  // One real anchor (apex) so that CE search succeeds; the rest are random
  // hashes that form genuine gaps.
  const NAMES = [
    'example.com',
    'www.example.com',
    'mail.example.com',
    'foo.bar.example.com',
  ];
  const known = NAMES.map((n) => hashName(n, saltHex, iterations).toString('hex'));

  // Data generation is harness work, not part of the validated algorithm, so
  // it is done before the timed window.
  const pool = crypto.randomBytes(20 * N);
  const owners = new Array(N);
  for (let i = 0; i < N; i++) {
    owners[i] = i < known.length
      ? known[i]
      : pool.toString('hex', i * 20, (i + 1) * 20);
  }
  owners.sort();
  // Deduplicate (random collisions are astronomically unlikely, but be safe).
  const recs = [];
  for (let i = 0; i < owners.length; i++) {
    if (i > 0 && owners[i] === owners[i - 1]) continue;
    recs.push({ owner: owners[i], next: '', flags: 0, salt: saltHex, iterations });
  }
  for (let i = 0; i < recs.length; i++) recs[i].next = recs[(i + 1) % recs.length].owner;

  const queries = new Array(Q);
  for (let i = 0; i < Q; i++) queries[i] = 'q' + i + '.example.com';

  const t0 = Date.now();
  const chain = new Nsec3Chain(recs);
  const tBuild = Date.now() - t0;

  const t1 = Date.now();
  let nx = 0;
  let bogus = 0;
  for (let i = 0; i < Q; i++) {
    const r = chain.validate(queries[i]);
    if (r.verdict === 'NXDOMAIN') nx++;
    if (r.verdict === 'BOGUS') bogus++;
  }
  const tQuery = Date.now() - t1;
  console.log('      build=' + tBuild + 'ms query=' + tQuery + 'ms nx=' + nx + ' bogus=' + bogus);
  assert.strictEqual(bogus, 0, 'no query should be BOGUS');
  assert.ok(tBuild + tQuery < 5000, 'total ' + (tBuild + tQuery) + 'ms exceeds 5s');
});

